void Solver::restart() {
    // Reset LBD statistics
    fast_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;

    // Backtrack to root level
    backtrack(0);

    // Reset activity scaling factor to avoid overflow and give fresh VSIDS scores
    var_inc = 1.0;

    // Rephase variables: alternate between random polarity and flipping previous saved polarity
    int flip = (conflicts / 1000) % 2;  // change pattern every 1000 conflicts
    for (int i = 1; i <= vars; ++i) {
        if (flip) {
            // Flip the previously saved polarity
            saved[i] = -saved[i];
        } else {
            // Assign a fresh random polarity
            saved[i] = (rand() % 2) ? 1 : -1;
        }
    }

    // Reduce the restart threshold to keep the search space manageable
    if (threshold > 200) threshold = threshold / 2;
    else threshold = 200;
}
